<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Personal Expense Tracker</title>
<style>
  * { box-sizing: border-box; }
  body {
    font-family: Arial, Helvetica, sans-serif;
    margin: 0;
    padding: 20px;
    background: #f4f5f7;
    color: #222;
  }
  .wrap { max-width: 720px; margin: 0 auto; }
  h1 { font-size: 1.4rem; margin: 0 0 16px; }
  section {
    background: #fff;
    border: 1px solid #ddd;
    border-radius: 8px;
    padding: 16px;
    margin-bottom: 16px;
  }
  h2 { font-size: 1rem; margin: 0 0 12px; color: #444; }
  .form-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(130px, 1fr));
    gap: 8px;
    align-items: end;
  }
  label { display: block; font-size: 0.78rem; color: #555; margin-bottom: 3px; }
  input, select, button {
    width: 100%;
    padding: 8px;
    font-size: 0.9rem;
    border: 1px solid #bbb;
    border-radius: 5px;
    background: #fff;
  }
  button { cursor: pointer; }
  #add-expense {
    background: #2f6fed;
    border-color: #2f6fed;
    color: #fff;
    font-weight: bold;
  }
  #add-expense:hover { background: #245bd0; }
  #form-error {
    color: #c0392b;
    font-size: 0.85rem;
    min-height: 1.1em;
    margin-top: 8px;
  }
  .filters-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
    gap: 8px;
  }
  #total-box {
    font-size: 1.05rem;
    font-weight: bold;
    margin-bottom: 10px;
  }
  #cat-summary { display: flex; flex-wrap: wrap; gap: 8px; }
  .cat-total {
    background: #eef2fb;
    border: 1px solid #cdd9f2;
    border-radius: 5px;
    padding: 5px 10px;
    font-size: 0.82rem;
  }
  #expense-list { list-style: none; margin: 0; padding: 0; }
  .expense {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 9px 6px;
    border-bottom: 1px solid #eee;
    font-size: 0.9rem;
  }
  .expense:last-child { border-bottom: none; }
  .exp-amount { font-weight: bold; min-width: 80px; }
  .exp-cat {
    background: #e8ecf3;
    border-radius: 4px;
    padding: 2px 8px;
    font-size: 0.78rem;
    text-transform: capitalize;
  }
  .exp-date { color: #666; font-size: 0.82rem; }
  .exp-note { color: #777; font-size: 0.82rem; flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .exp-del {
    width: auto;
    background: #fdecea;
    border: 1px solid #f5c6c0;
    color: #c0392b;
    padding: 4px 10px;
    font-size: 0.78rem;
    margin-left: auto;
  }
  .exp-del:hover { background: #f9d7d2; }
  #empty-msg { color: #888; font-size: 0.88rem; padding: 8px 4px; }
</style>
</head>
<body>
<div class="wrap">
  <h1>Personal Expense Tracker</h1>

  <section>
    <h2>Add Expense</h2>
    <form id="expense-form" novalidate>
      <div class="form-grid">
        <div>
          <label for="amount">Amount</label>
          <input id="amount" type="number" step="0.01" min="0" placeholder="0.00">
        </div>
        <div>
          <label for="category">Category</label>
          <select id="category">
            <option value="groceries">groceries</option>
            <option value="transport">transport</option>
            <option value="bills">bills</option>
            <option value="fun">fun</option>
          </select>
        </div>
        <div>
          <label for="date">Date</label>
          <input id="date" type="date">
        </div>
        <div>
          <label for="note">Note (optional)</label>
          <input id="note" type="text" placeholder="e.g. weekly shop">
        </div>
        <div>
          <button id="add-expense" type="submit">Add Expense</button>
        </div>
      </div>
      <div id="form-error" role="alert"></div>
    </form>
  </section>

  <section>
    <h2>Filters</h2>
    <div class="filters-grid">
      <div>
        <label for="filter-category">Category</label>
        <select id="filter-category">
          <option value="all">all</option>
          <option value="groceries">groceries</option>
          <option value="transport">transport</option>
          <option value="bills">bills</option>
          <option value="fun">fun</option>
        </select>
      </div>
      <div>
        <label for="filter-from">From</label>
        <input id="filter-from" type="date">
      </div>
      <div>
        <label for="filter-to">To</label>
        <input id="filter-to" type="date">
      </div>
    </div>
  </section>

  <section>
    <h2>Summary (visible expenses)</h2>
    <div id="total-box">Total: <span id="total">0.00</span></div>
    <div id="cat-summary"></div>
  </section>

  <section>
    <h2>Expenses</h2>
    <ul id="expense-list"></ul>
    <div id="empty-msg" hidden>No expenses to show.</div>
  </section>
</div>

<script>
(function () {
  "use strict";

  var CATEGORIES = ["groceries", "transport", "bills", "fun"];
  var STORAGE_KEY = "expenses";

  var amountEl = document.getElementById("amount");
  var categoryEl = document.getElementById("category");
  var dateEl = document.getElementById("date");
  var noteEl = document.getElementById("note");
  var formEl = document.getElementById("expense-form");
  var errorEl = document.getElementById("form-error");
  var listEl = document.getElementById("expense-list");
  var emptyMsg = document.getElementById("empty-msg");
  var totalEl = document.getElementById("total");
  var catSummaryEl = document.getElementById("cat-summary");
  var filterCategoryEl = document.getElementById("filter-category");
  var filterFromEl = document.getElementById("filter-from");
  var filterToEl = document.getElementById("filter-to");

  var expenses = loadExpenses();

  function loadExpenses() {
    try {
      var raw = localStorage.getItem(STORAGE_KEY);
      var data = raw ? JSON.parse(raw) : [];
      return Array.isArray(data) ? data : [];
    } catch (e) {
      return [];
    }
  }

  function saveExpenses() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(expenses));
  }

  function passesFilters(expense) {
    var fc = filterCategoryEl.value;
    if (fc !== "all" && expense.category !== fc) return false;
    var from = filterFromEl.value;
    if (from && expense.date < from) return false;
    var to = filterToEl.value;
    if (to && expense.date > to) return false;
    return true;
  }

  function buildCatSummary() {
    catSummaryEl.innerHTML = "";
    CATEGORIES.forEach(function (cat) {
      var div = document.createElement("div");
      div.className = "cat-total";
      div.setAttribute("data-cat", cat);
      catSummaryEl.appendChild(div);
    });
  }

  function render() {
    listEl.innerHTML = "";

    var visibleTotal = 0;
    var catTotals = {};
    CATEGORIES.forEach(function (c) { catTotals[c] = 0; });
    var anyVisible = false;

    // expenses array is kept newest-first
    expenses.forEach(function (expense) {
      var visible = passesFilters(expense);

      var li = document.createElement("li");
      li.className = "expense";
      li.setAttribute("data-id", expense.id);
      if (!visible) li.style.display = "none";

      var amountSpan = document.createElement("span");
      amountSpan.className = "exp-amount";
      amountSpan.textContent = expense.amount.toFixed(2);

      var catSpan = document.createElement("span");
      catSpan.className = "exp-cat";
      catSpan.textContent = expense.category;

      var dateSpan = document.createElement("span");
      dateSpan.className = "exp-date";
      dateSpan.textContent = expense.date;

      var noteSpan = document.createElement("span");
      noteSpan.className = "exp-note";
      noteSpan.textContent = expense.note || "";

      var delBtn = document.createElement("button");
      delBtn.type = "button";
      delBtn.className = "exp-del";
      delBtn.textContent = "Delete";

      li.appendChild(amountSpan);
      li.appendChild(catSpan);
      li.appendChild(dateSpan);
      if (expense.note) li.appendChild(noteSpan);
      li.appendChild(delBtn);
      listEl.appendChild(li);

      if (visible) {
        anyVisible = true;
        visibleTotal += expense.amount;
        if (catTotals.hasOwnProperty(expense.category)) {
          catTotals[expense.category] += expense.amount;
        }
      }
    });

    emptyMsg.hidden = anyVisible;

    totalEl.textContent = visibleTotal.toFixed(2);

    var catDivs = catSummaryEl.querySelectorAll(".cat-total");
    Array.prototype.forEach.call(catDivs, function (div) {
      var cat = div.getAttribute("data-cat");
      div.textContent = cat + ": " + (catTotals[cat] || 0).toFixed(2);
    });
  }

  formEl.addEventListener("submit", function (e) {
    e.preventDefault();

    var rawAmount = amountEl.value.trim();
    var amount = parseFloat(rawAmount);
    var date = dateEl.value;

    if (rawAmount === "" || !isFinite(amount)) {
      errorEl.textContent = "Please enter a valid numeric amount.";
      return;
    }
    if (amount <= 0) {
      errorEl.textContent = "Amount must be greater than zero.";
      return;
    }
    if (!date) {
      errorEl.textContent = "Please choose a date.";
      return;
    }

    errorEl.textContent = "";

    expenses.unshift({
      id: Date.now().toString(36) + Math.random().toString(36).slice(2, 8),
      amount: Math.round(amount * 100) / 100,
      category: categoryEl.value,
      date: date,
      note: noteEl.value.trim()
    });

    saveExpenses();
    render();

    amountEl.value = "";
    noteEl.value = "";
    amountEl.focus();
  });

  listEl.addEventListener("click", function (e) {
    var btn = e.target.closest ? e.target.closest(".exp-del") : null;
    if (!btn) return;
    var li = btn.closest(".expense");
    if (!li) return;
    var id = li.getAttribute("data-id");
    expenses = expenses.filter(function (x) { return x.id !== id; });
    saveExpenses();
    render();
  });

  filterCategoryEl.addEventListener("change", render);
  filterFromEl.addEventListener("change", render);
  filterFromEl.addEventListener("input", render);
  filterToEl.addEventListener("change", render);
  filterToEl.addEventListener("input", render);

  buildCatSummary();
  render();
})();
</script>
</body>
</html>
